    'global.emails.user_data_collected.subject' => 'Új adatok ehhez: \'{{BLOCK_TITLE}}\': {{WEBSITE_TITLE}}',
    'global.emails.user_data_collected_phone_collector.body' => 'Szia, <strong>{{NAME}}</strong>!<br /><br />Az egyik látogatód új adatokat küldött be a <strong>Phone Collector</strong> űrlapon keresztül.<br /><br /><strong>Telefonszám:</strong> {{DATA_PHONE}}<br /><strong>Név:</strong> {{DATA_NAME}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Az összegyűjtött adatok megtekintése</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.user_data_collected_email_collector.body' => 'Szia, <strong>{{NAME}}</strong>,<br /><br />Új adatbeküldés érkezett az <strong>Email Collector</strong> eszközből az egyik látogatódtól.<br /><br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Név:</strong> {{DATA_NAME}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Az összes összegyűjtött adat megtekintése</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.user_data_collected_contact_collector.body' => 'Szia, <strong>{{NAME}}</strong>!<br /><br />Az egyik látogatód új adatokat küldött be a <strong>Kapcsolatfelvételi űrlapon</strong>.<br /><br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Telefonszám:</strong> {{DATA_PHONE}}<br /><strong>Név:</strong> {{DATA_NAME}}<br /><strong>Üzenet:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Az összes összegyűjtött adat megtekintése</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.user_data_collected_appointment_calendar.body' => 'Szia, <strong>{{NAME}}</strong>!<br /><br />Az egyik látogatód új időpontot foglalt az <strong>Időpontnaptárban</strong>.<br /><br /><strong>Dátum:</strong> {{DATA_DATE}}<br /><strong>Idő:</strong> {{DATA_TIME}}<br /><strong>Időtartam:</strong> {{DATA_DURATION}}<br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Telefon:</strong> {{DATA_PHONE}}<br /><strong>Név:</strong> {{DATA_NAME}}<br /><strong>Üzenet:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Az összes összegyűjtött adat megtekintése</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.user_guest_payment_donation.subject' => '{{TOTAL_AMOUNT}} {{CURRENCY}} adomány a(z) „{{DONATION_TITLE}}” céljára: {{WEBSITE_TITLE}}',
    'global.emails.user_guest_payment_donation.body' => 'Szia, <strong>{{NAME}}</strong>,<br /><br />Az egyik látogatód adományt küldött neked.<br /><br /><strong>E-mail:</strong> {{EMAIL}}<br /><strong>Név:</strong> {{PAYER_NAME}}<br /><strong>Teljes összeg:</strong> {{TOTAL_AMOUNT}}<br /><strong>Pénznem:</strong> {{CURRENCY}}<br /><strong>Fizetési szolgáltató:</strong> {{PROCESSOR}}<br /><strong>Adomány:</strong> {{DONATION_TITLE}}<br /><strong>Üzenet:</strong> {{MESSAGE}}<br /><br /><a href="{{GUEST_PAYMENT_LINK}}" class="cta">Fizetés megtekintése</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
