    'global.emails.guest_guest_payment_product.subject' => 'Megvásároltad a \'{{PRODUCT_TITLE}}\' terméket: {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_product.body' => 'Szia, <strong>{{NAME}}</strong>,<br /><br />Ez a hivatalos e-mailes értesítés arról, hogy a rendelésed sikeres volt. A megvásárolt termék letöltéséhez használd az alábbi hivatkozást.<br /><br /><strong>Letöltési hivatkozás:</strong> {{DOWNLOAD_LINK}}<br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
