    'global.emails.guest_guest_payment_service.subject' => 'Kifizetted a(z) „{{SERVICE_TITLE}}” szolgáltatást: {{WEBSITE_TITLE}}',
    'global.emails.guest_guest_payment_service.body' => 'Helló, <strong>{{NAME}}</strong>,<br /><br />Ez a hivatalos e-mailes értesítés arról, hogy a rendelésed sikeres volt. A szolgáltató a lehető leghamarabb felveszi veled a kapcsolatot.<br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.user_plan_expiry_reminder.subject' => 'Az előfizetésed {{DAYS_UNTIL_EXPIRATION}} nap múlva lejár: {{WEBSITE_TITLE}}',
