    'global.emails.user_plan_expired.subject' => 'A csomagod lejárt: {{WEBSITE_TITLE}}',
    'global.emails.user_plan_expired.body' => 'Szia, <strong>{{NAME}}</strong>,<br /><br />A <strong>{{PLAN_NAME}} csomagod</strong> lejárt, mert nem újítottad meg a tagságodat.<br /><br />Ha továbbra is szeretnéd használni weboldalunk összes funkcióját, meg kell újítanod a tagságodat.<br /><br /><a href="{{USER_PLAN_RENEW_LINK}}" class="cta">Csomag megújítása</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
