    'global.emails.user_deletion_reminder.body' => 'Helló, <strong>{{NAME}}</strong>,<br /><br />Ez az egyszerű e-mail emlékeztet, hogy fiókodat {{DAYS_UNTIL_DELETION}} nap múlva töröljük, mert inaktív volt.<br /><br />Ha szeretnéd megszakítani a törlést, egyszerűen jelentkezz be a fiókodba, és a törlési folyamat leáll.<br /><br /><a href="{{LOGIN_LINK}}">Bejelentkezés és törlés leállítása</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
    'global.emails.auto_delete_inactive_users.subject' => 'A fiókodat töröltük: {{WEBSITE_TITLE}}',
    'global.emails.auto_delete_inactive_users.body' => 'Szia, <strong>{{NAME}}</strong>,<br /><br />Ezzel az egyszerű e-maillel értesítünk, hogy töröltük a fiókodat, mert több mint {{INACTIVITY_DAYS}} napja inaktív volt.<br /><br />Ha újra hozzá szeretnél férni, új fiókot kell regisztrálnod nálunk.<br /><br /><a href="{{REGISTER_LINK}}" class="cta">Regisztrálj újra</a><br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
