    'global.emails.team_member_create.body_register' => 'Szia,<br /><br /><strong>{{USER:NAME}}</strong> ({{USER:EMAIL}}) meghívott, hogy csatlakozz a <strong>{{TEAM:NAME}}</strong> csapathoz a következő oldalon: {{WEBSITE_TITLE}}.<br /><br />Kattints ide a <a href="{{REGISTER_LINK}}" class="cta">regisztrációhoz és a meghívás elfogadásához</a>.<br /><br />Üdvözlettel,<br />A {{WEBSITE_TITLE}} csapata.',
