    'dashboard.dynamic.conversion_registration_gap' => 'Vannak kattintások a Forever felé, de most erősíteni kell a regisztrációkhoz és kapcsolatfelvételekhez vezető utat.',
    'dashboard.dynamic.conversion_leads' => 'A tölcsérből és az MI-csevegésből már érkeznek érdeklődők. Most az a cél, hogy megtartsd a legjobban működő csatornát, és tovább erősítsd azt, ami már bevált.',
    'dashboard.dynamic.contacts_breakdown_both' => 'Funnel {funnel} · AI-csevegés {chat}',
