    'dashboard.dynamic.blocker_funnel_no_leads' => 'Van forgalom az értékesítési tölcsérben, de még nem alakul át elég érdeklődővé.',
    'dashboard.dynamic.blocker_repeated_issue' => 'Ugyanaz a probléma ismétlődik az ügyfélszolgálati megkeresésekben, ezért érdemes webináriumtémaként felvetni.',
    'dashboard.dynamic.next_action_fallback_title' => 'Összpontosíts a legjobb csatornára',
    'dashboard.dynamic.next_action_fallback_description' => 'A rendszer jelenleg nem lát sürgős akadályt, ezért az a legjobb, ha megismétled azt a tartalmat, amely már hoz kattintásokat, és megerősíted a cselekvésre ösztönző felhívást.',
    'dashboard.dynamic.support_repeated_issue' => 'Úgy tűnik, ugyanaz a téma újra és újra előkerül. Érdemes javaslatot küldened, hogy a következő webináriumon foglalkozhassunk vele.',
