    'dashboard.dynamic.channel_app_badge' => 'FCC-alkalmazás',
    'dashboard.dynamic.channel_app_title' => 'FCC-alkalmazás',
    'dashboard.dynamic.channel_app_copy' => 'Az FCC-alkalmazásodból a Forever webáruház felé irányuló kattintások.',
    'dashboard.dynamic.channel_blog_badge' => 'Blogbejegyzés',
    'dashboard.dynamic.channel_blog_title' => 'Megosztott blogcikk',
    'dashboard.dynamic.channel_blog_copy' => 'A megosztott blogcikkeidből a Forever webáruházba vezető kattintások.',
    'dashboard.onboarding_intro.eyebrow' => 'FCC-útmutató',
    'dashboard.onboarding_intro.title' => 'Kezdd egyszerűen, és lásd át egy helyen, hogy mi áll már rendelkezésedre',
    'dashboard.onboarding_intro.text' => 'Az FCC személyes alkalmazást, blogtartalmakat, tölcséreszközöket, támogatást és AI-ajánlásokat ad neked, hogy nagyobb érdeklődést kelthess a Forever termékek, a regisztráció és a kapcsolatfelvétel iránt.',
    'dashboard.onboarding_intro.item_1_title' => 'FCC-alkalmazások és megosztható hivatkozások',
    'dashboard.onboarding_intro.item_1_text' => 'Szerkeszd az alkalmazásodat, és ossz meg olyan linkeket, amelyek az ajánlásodhoz vezetnek.',
    'dashboard.onboarding_intro.item_2_title' => 'Kattintások, regisztrációk és kapcsolatok',
    'dashboard.onboarding_intro.item_2_text' => 'Azonnal láthatod, mi kelti fel az érdeklődést, hol történnek regisztrációk és kapcsolatfelvételek, és mit érdemes megismételni.',
    'dashboard.onboarding_intro.item_3_title' => 'AI és támogatás',
    'dashboard.onboarding_intro.item_3_text' => 'Az AI segít a következő lépésekben, a támogatási felületen pedig kérdéseket tehetsz fel és webinárium-témákat javasolhatsz.',
    'dashboard.onboarding_intro.primary' => 'Oktatóanyag indítása',
    'dashboard.onboarding_intro.secondary' => 'Hogyan működik az FCC',
    'dashboard.onboarding_modal.title' => 'Hogyan működik az FCC',
    'dashboard.onboarding_modal.subtitle' => '6 rövid lépésben megnézheted, mid van, mit nyújt, és mivel érdemes kezdened.',
    'dashboard.onboarding_modal.step_1_title' => '1. Az irányítópult mint kiindulópont',
    'dashboard.onboarding_modal.step_1_text' => 'Az irányítópult az FCC-rendszer megértésének fő felülete. Itt láthatod az aktivitásodat, az oktatási útmutatókat, a következő teendőket, valamint az áttekintést arról, mi hoz már eredményeket.',
    'dashboard.onboarding_modal.step_2_title' => '2. Főmenük és tartalom',
    'dashboard.onboarding_modal.step_2_text' => 'A főmenüből nyithatod meg a Forever Card Club tartalmait, a Forever termékeket, a blogot, a kapcsolatfelvételi oldalt és az irányítópultot. Ezen az útvonalon tanulhatsz, oszthatsz meg tartalmakat és építheted a Forever üzletedet.',
    'dashboard.onboarding_modal.step_3_title' => '3. FCC-alkalmazások és linkek',
    'dashboard.onboarding_modal.step_3_text' => 'Az FCC-alkalmazásaid személyes digitális bázisként működnek, ahonnan a látogatókat a termékek, regisztrációk, kapcsolatfelvétel és más fontos műveletek felé irányíthatod.',
    'dashboard.onboarding_modal.step_4_title' => '4. Blog és ajánlások',
    'dashboard.onboarding_modal.step_4_text' => 'A blogot és a Forever Products részt oktató és termékekkel kapcsolatos tartalmak megosztására használhatod. A saját ajánlásod révén a termékek iránti érdeklődés és a webáruház is hozzád kapcsolódik.',
    'dashboard.onboarding_modal.step_5_title' => '5. Signal, AI és a fejlődési terved',
    'dashboard.onboarding_modal.step_5_text' => 'Az FCC nyomon követi, hogy mely tevékenységek vezetnek ténylegesen a Forever webáruházhoz, az AI pedig ezt a jelzést használja arra, hogy egyértelműbb következő lépéseket és jobb növekedési tervet javasoljon.',
    'dashboard.onboarding_modal.step_6_title' => '6. Támogatási, oktatási és webináriumtémák',
    'dashboard.onboarding_modal.step_6_text' => 'Ha elakadsz, vagy új irányt keresel, a támogatás és a webináriumok témái további magyarázatot és segítséget nyújtanak, és lehetőséget adnak arra is, hogy javaslatot tegyél arra, mi lenne a legfontosabb a fejlődésed következő szakaszában.',
    'dashboard.onboarding_modal.primary' => 'Oktatóanyag indítása',
    'dashboard.onboarding_modal.secondary' => 'Csak mutasd meg, mi merre van',
    'dashboard.tutorials.eyebrow' => 'Rövid útmutatók',
    'dashboard.tutorials.title' => 'Útmutatók az első ajánlásaidhoz',
    'dashboard.tutorials.text' => 'Nyiss meg rövid útmutatókat olyan konkrét lépésekhez, amelyekkel az FCC rendszeren keresztül növelheted az érdeklődést, a kattintások és az ajánlások számát.',
    'dashboard.tutorials.blog_referral.badge' => 'FCC blog és ajánlás',
    'dashboard.tutorials.blog_referral.title' => 'Ossz meg egy cikket a saját ajánlólinked segítségével',
    'dashboard.tutorials.blog_referral.text' => 'Ez az útmutató végigvezet a Forever termékek résztől egy kész linkig, amely automatikusan összekapcsolja a tartalmadat, az ajánlásodat és a webshoplátogatást.',
    'dashboard.tutorials.blog_referral.button' => 'Kezdési útmutató',
    'dashboard.tutorials.blog_referral.modal_title' => 'Hogyan oszthatsz meg egy cikket a saját ajánlói linkeddel',
    'dashboard.tutorials.blog_referral.modal_subtitle' => 'A Forever Products szekció megnyitásától egy kész, az ajánlásodat már tartalmazó link kimásolásáig.',
    'dashboard.tutorials.blog_referral.modal_callout' => 'Ha így osztasz meg egy cikket, az FCC automatikusan hozzáadja az ajánlásodat az elküldött linkhez. Így a legegyszerűbb, hogy a terméktartalom rögtön a jelzéseddel és az ajánlásoddal együtt működjön.',
    'dashboard.tutorials.blog_referral.modal_primary' => 'Útmutató indítása lépésről lépésre',
    'dashboard.tutorials.blog_referral.next_open_article' => 'Cikk megnyitása',
    'dashboard.tutorials.blog_referral.step_1_title' => '1. Kattints a Forever Products elemre',
    'dashboard.tutorials.blog_referral.step_1_text' => 'Nyisd meg a bal oldali menüben a Forever Products részt. Ezzel a megosztásra kész terméktartalmakat tartalmazó blogba jutsz.',
    'dashboard.tutorials.blog_referral.step_2_title' => '2. Válassz egy terméket, vagy keresd meg a keresővel',
    'dashboard.tutorials.blog_referral.step_2_text' => 'A blogon válaszd ki a terméket, amelyet ajánlani szeretnél. Ha gyorsabban meg szeretnéd találni a megfelelő cikket, használj keresést, majd nyisd meg azt a terméket, amely megfelel az illető érdeklődésének.',
    'dashboard.tutorials.blog_referral.step_3_title' => '3. Használd az ajánlást tartalmazó megosztási felületet',
    'dashboard.tutorials.blog_referral.step_3_text' => 'A cikk tetején találod az „Oszd meg ezt az oldalt az ajánlásoddal” részt. Itt kimásolhatod a hivatkozást, vagy az elérhető gombokkal azonnal megoszthatod.',
    'dashboard.tutorials.blog_referral.step_4_title' => '4. A hivatkozás már tartalmazza az ajánlásodat',
    'dashboard.tutorials.blog_referral.step_4_text' => 'A másolt vagy megosztott link már tartalmazza az egyedi ajánlói linkedet. Ha egy látogató ezen keresztül nyitja meg a Forever webáruházat, a látogatás és az ajánlás össze lesz kapcsolva a fiókoddal.',
    'dashboard.tutorials.blog_referral.step_5_title' => 'Miért fontos ez?',
    'dashboard.tutorials.blog_referral.step_5_text' => 'Ezek a kattintások erősítik az értékesítési jelzéseidet, segítenek előtérbe helyezni a Forever Card alkalmazásodat, és jól követhető érdeklődési útvonalat alakítanak ki a Forever Living Products felé.',
    'dashboard.tutorials.blog_referral.category_step_1_title' => 'Most a Forever termékek között vagy',
    'dashboard.tutorials.blog_referral.category_step_1_text' => 'Ez a termékblog tartalmi része, amelyet az ajánlásoddal együtt megoszthatsz. Az útmutató most a megfelelő cikkhez és a megosztható ajánlói linkhez vezet.',
    'dashboard.tutorials.blog_referral.category_step_2_title' => 'Keresd meg az ajánlani kívánt terméket',
    'dashboard.tutorials.blog_referral.category_step_2_text' => 'Ha már tudod, melyik terméket szeretnéd elküldeni, írd be a keresőbe. Így jutsz el a leggyorsabban ahhoz a cikkhez, amely megfelel az illető érdeklődésének.',
    'dashboard.tutorials.blog_referral.category_step_3_title' => 'Nyisd meg a termékről szóló cikket',
    'dashboard.tutorials.blog_referral.category_step_3_text' => 'Ehhez az útmutatóhoz megnyitjuk az első látható cikket. A cikkben az útmutató folytatódik, és megmutatja, hol másolhatod ki vagy oszthatod meg az ajánlói linkedet.',
    'dashboard.tutorials.blog_referral.article_step_1_title' => 'Itt jön létre az ajánlási link',
    'dashboard.tutorials.blog_referral.article_step_1_text' => 'A cikk tetején láthatod a megosztási sort az ajánlásoddal. Ha innen osztod meg, az FCC hozzáadja a személyes ajánlásodat a hivatkozáshoz.',
    'dashboard.tutorials.blog_referral.article_step_2_title' => 'Ellenőrizd, hogyan működik a rendszer',
    'dashboard.tutorials.blog_referral.article_step_2_text' => 'A „Hogyan működik?” gombra kattintva egy rövid magyarázat nyílik meg arról, hogy az ajánlásod automatikusan hozzáadódik, a látogatás pedig továbbra is a fiókodhoz kapcsolódik.',
    'dashboard.tutorials.blog_referral.article_step_3_title' => 'Oszd meg a cikket az előre elkészített gombokkal',
    'dashboard.tutorials.blog_referral.article_step_3_text' => 'Itt azonnal megoszthatod a cikket a közösségi oldalakon, vagy elküldheted üzenetben. Minden lehetőség ugyanazt a linket használja, benne az ajánlásoddal.',
    'dashboard.tutorials.blog_referral.article_step_4_title' => 'Másold ki a kész linkedet',
    'dashboard.tutorials.blog_referral.article_step_4_text' => 'Ha manuálisan szeretnéd beilleszteni a hivatkozást egy üzenetbe, történetbe vagy bejegyzésbe, másold ki innen. Ha valaki ezen a hivatkozáson keresztül nyitja meg a Forever webáruházat, továbbra is a te ajánlásodhoz kapcsolódik.',
    'dashboard.tour.launch' => 'Oktatóanyag indítása',
    'dashboard.tour.replay' => 'Oktatóvideó újbóli lejátszása',
    'dashboard.tour.next' => 'Következő',
    'dashboard.tour.prev' => 'Vissza',
    'dashboard.tour.skip' => 'Kihagyás',
    'dashboard.tour.finish' => 'Befejezés',
    'dashboard.tour.step_guide_title' => 'Útmutató ehhez az oldalhoz',
    'dashboard.tour.step_guide_text' => 'Minden fontos FCC-oldalon az útmutatót a jobb felső sarokban találod. Kattints erre a gombra, ha rövid, lépésről lépésre szóló útmutatást szeretnél az éppen megtekintett oldalhoz.',
    'dashboard.tour.step_sidebar_title' => 'FCC-menü és munkaterületek',
    'dashboard.tour.step_sidebar_text' => 'Ez a fő FCC-menü a felhasználói rendszereden belül. Innen nyithatod meg az irányítópultot, az alkalmazásokat, a fejlődési tervedet, az eredményeidet, az oktatóanyagokat és a mindennapi Forever-üzletedet támogató terméktartalmakat.',
    'dashboard.tour.step_menu_apps_title' => 'FCC-alkalmazások',
    'dashboard.tour.step_menu_apps_text' => 'Itt nyithatod meg a Forever Card alkalmazásaidat. Ezek a személyes digitális bázisaid, amelyekkel a látogatókat a termékekhez, regisztrációkhoz, kapcsolatokhoz és más fontos műveletekhez irányíthatod.',
    'dashboard.tour.step_menu_ai_plan_title' => 'AI-növekedési terv',
    'dashboard.tour.step_menu_ai_plan_text' => 'Itt nyithatod meg és követheted a fejlődési tervedet. A mesterséges intelligencia az alkalmazásaidból, a blogtartalmaidból és a webáruházi kattintásokból származó adatok alapján javaslatot tesz arra, mi legyen a következő legjobb lépésed az elkövetkező napokban.',
    'dashboard.tour.step_menu_results_title' => 'FCC-eredmények',
    'dashboard.tour.step_menu_results_text' => 'Itt láthatod, hogy a rendszered valóban hoz-e eredményeket. Ezen a felületen nyomon követheted a kattintásokat, az előrehaladást és azokat a jelzéseket, amelyek megmutatják, min érdemes javítani.',
    'dashboard.tour.step_menu_education_title' => 'Forever oktatás',
    'dashboard.tour.step_menu_education_text' => 'Ez a terület videós oktatóanyagokat és magyarázatokat tartalmaz, amelyek segítenek megérteni a rendszert, követni a lépéseket, és a tanultakat a mindennapi munkában alkalmazni.',
    'dashboard.tour.step_menu_products_title' => 'Forever termékek',
    'dashboard.tour.step_menu_products_text' => 'Itt találod a termékcikkeket és az ajánlásokkal kapcsolatos tartalmakat. Ez az egyik legfontosabb felület, ahol tartalmakat oszthatsz meg az ajánlásoddal, és a Forever webáruház felé terelheted az érdeklődőket.',
    'dashboard.tour.step_navbar_title' => 'FCC főmenü',
    'dashboard.tour.step_navbar_text' => 'A felső menüben navigálhatsz a képzések, a termékek, a blogbejegyzések és a kapcsolati adatok között, illetve innen térhetsz vissza az irányítópultra. Itt kezdődik az FCC teljes rendszerének megismerése.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Itt találod az FCC alapvető információit, a rendszer magyarázatait és azokat a tartalmakat, amelyek segítenek megérteni, hogyan működnek együtt az alkalmazások, az ajánlások és az eszközök egy Forever-üzlet felépítésében.',
    'dashboard.tour.step_menu_forever_products_title' => 'Forever termékek',
    'dashboard.tour.step_menu_forever_products_text' => 'Itt olyan terméktartalmakat és cikkeket találsz, amelyeket ajánlásoddal együtt megoszthatsz. Ez fontos része annak, hogy felkeltsd az érdeklődést, és a Forever webáruház felé irányítsd a látogatókat.',
    'dashboard.tour.step_menu_blog_title' => 'Blog',
    'dashboard.tour.step_menu_blog_text' => 'A blog szélesebb körű oktatási és üzleti tartalmakat kínál, amelyeket bejegyzésekben és üzenetekben használhatsz, valamint hasznos tartalmakkal építheted a bizalmat, nem csak közvetlen értékesítéssel.',
    'dashboard.tour.step_menu_contact_title' => 'Kapcsolat',
    'dashboard.tour.step_menu_contact_text' => 'Itt kapcsolatot és támogatást találsz a további kérdésekhez. Ha valami nem világos, vagy útmutatásra van szükséged, itt kérhetsz segítséget.',
    'dashboard.tour.step_menu_dashboard_title' => 'Ugrás az irányítópultra',
    'dashboard.tour.step_menu_dashboard_text' => 'Az irányítópult a központod. Itt követheted a jelzéseidet, útmutatókból tanulhatsz, megnézheted, mi működik, és eldöntheted, mi legyen a következő lépésed.',
    'dashboard.tour.step_hero_title' => 'Az FCC-munkád kezdőlapja',
    'dashboard.tour.step_hero_text' => 'Ez a felső szakasz összefoglalja, hol tartasz, mire összpontosítasz, és melyek a leggyorsabb belépési pontok az alkalmazásokhoz, a támogatáshoz és az oktatóanyagokhoz.',
    'dashboard.tour.step_growth_title' => 'Jelzések és feloldások',
    'dashboard.tour.step_growth_text' => 'Itt láthatod, hogy az FCC-alkalmazásodon, blogodon és más eszközeiden keresztül mennyi valódi aktivitás vezet a Forever Living webshophoz. Ez a jelzés befolyásolja az AI-segítség ütemét és a növekedési terved következő feloldásait.',
    'dashboard.tour.step_tutorials_title' => 'Rövid oktatóanyagok és képzés',
    'dashboard.tour.step_tutorials_text' => 'Itt rövid, gyakorlatias útmutatókat találsz egyes teendőkhöz. Így működik a gyakorlatban az FCC képzése: nemcsak elméletet kínál, hanem apró lépéseket is, amelyeket azonnal alkalmazhatsz.',
    'dashboard.tour.step_workbench_title' => 'Munkafelület',
    'dashboard.tour.step_workbench_text' => 'Itt rögtön láthatod, mi működik, hol vész el az eredmény, és a rendszer mely részei keltenek már érdeklődést. Így találgatás helyett valós jelzések alapján hozhatsz döntéseket.',
    'dashboard.tour.step_chart_title' => 'Az eredményt hozó kattintások',
    'dashboard.tour.step_chart_text' => 'A diagram külön mutatja az alkalmazásból a Foreverhez, a blogból a Foreverhez vezető utakat, a regisztrációkat, valamint a tölcsérből és az AI-csevegésből érkező kapcsolatokat, hogy egyértelműen lásd, a rendszer melyik része hoz valódi üzleti eredményt.',
    'dashboard.tour.step_next_action_title' => 'A következő lépésed',
