    'fcc_results.proof_note' => 'Az FCC Results a tevékenységi mutatókat mutatja. A Featured Apps a nyilvános példákat jelöli 15+ / 30d értékkel, az 50+ / 30d pedig tovább erősíti az utat a kezdőlapon ajánlott szponzori státusz felé.',
    'fcc_results.metrics_note' => 'A küszöbök és rangsorok az általános és a külön erre a célra szolgáló gombokon, valamint blogokon keresztül érkező, minősített Forever-látogatásokat veszik figyelembe, az ismételt látogatások kiszűrésével. Egy UTM-címke önmagában nem ér pontot. A VIP-tölcsér minősítéshez való hozzájárulása külön jelenik meg, a többi tölcsérből és az AI-csevegésből érkező kapcsolat pedig az érdeklődést jelzi.',
