    'ai_plan.signal_summary.watch_text_mobile' => 'A legtöbben telefonon nézik meg az oldaladat. Az első képernyőnek, az első üzenetnek és az első kattintásnak azonnal egyértelműnek kell lennie, túl sok görgetés és választási lehetőség nélkül.',
    'ai_plan.signal_summary.watch_text_funnel_early' => 'Az értékesítési lépések már megvannak, de a jelzés továbbra is gyenge. Ne bonyolítsd túl korán az útvonalat, ha még nincsenek minőségi kattintások.',
    'ai_plan.signal_summary.watch_text_country' => 'Jelenleg erről a piacról érkezik a legtöbb érdeklődés: %s. Gondoskodj róla, hogy az üzenet, a példa és az ajánlat világos legyen ennek a közönségnek.',
    'ai_plan.status_card_title' => 'Jelenlegi állapotod',
    'ai_plan.status_card_text_profile' => 'Egészítsd ki a profilodat, hogy az AI megértse a célodat, a célközönségedet és a munkamódszeredet.',
    'ai_plan.status_card_text_signal' => 'A profil létrejött, de még épül az érdeklődés. A cél, hogy további %s minőségi kattintás érkezzen a Forever Webshopból, így a heti tervnek már lesz valós alapja.',
    'ai_plan.status_card_text_weekly' => 'A jelzés készen áll. A legértékesebb következő lépés a heti állapotfelmérés kitöltése, hogy a rendszer általános javaslat helyett valódi heti tervet készíthessen.',
    'ai_plan.status_card_text_plan_pending' => 'Van heti állapotfelmérés, de a terv még nincs elmentve. Következő lépésként nyisd meg az aktuális tervet, vagy várd meg, amíg egy új heti beküldés alapján elkészül az új terv.',
    'ai_plan.status_card_text_execute' => 'A terv elkészült. Most arra összpontosíts, hogy túl sok új ötlet szétforgácsolása nélkül megvalósítsd, majd rögzítsd a tényleges eredményt.',
    'ai_plan.status_card_text_complete' => 'A legutóbbi ciklus véget ért. Az eredmény alapján most sokkal világosabb iránnyal kezdhetsz neki a következő heti ellenőrzésnek.',
