    'index.splash_pages.header' => 'Landing oldalak',
    'index.splash_pages.subheader' => 'Használj személyre szabott köztes oldalakat visszaszámlálóval a linkjeidhez.',
    'index.pixels.header' => 'Részletes analitika és teljesítménykövetés',
    'index.pixels.subheader' => 'Minden intelligens hivatkozás és a Forever Card Application integrálható a vezető analitikai és hirdetési platformokkal.',
    'index.pixels.note' => 'A követési adatok segítenek a partnereknek megérteni, mi működik: mely tartalmak keltenek érdeklődést, honnan érkeznek a látogatók, és mely kampányok hoznak eredményt. A rendszer támogatja a legfontosabb pixel- és követési szolgáltatókkal való integrációt.',
    'index.pricing.header' => 'Egyszerű, átlátható árak.',
    'index.testimonials.one.text' => 'Ez a platform teljesen átalakította a munkafolyamataink kezelését. Intuitív és gyors, és hetente számtalan munkaórát takarított meg a csapatunknak.',
    'index.testimonials.one.attribute' => 'A Writer\'s Weekly szerkesztője',
    'index.testimonials.two.text' => 'Eleinte szkeptikus voltam, de néhány nap alatt láttam, mennyivel hatékonyabb lett a csapatunk. A támogatói csapat ráadásul rendkívül gyorsan reagál.',
    'index.partners.header' => 'Miért használják a partnerek a Forever Card Clubot?',
    'index.partners.subheader' => 'Strukturált digitális rendszer a professzionális és nemzetközi Forever üzletépítéshez.',
    'index.partners.card1.title' => 'Egy rendszer, minden egy helyen',
    'index.partners.card1.text' => 'Személyes alkalmazás, okos linkek, oktatás, MI-támogatás és elemzések egyetlen digitális ökoszisztémában.',
    'index.partners.card2.title' => 'Globális útválasztás bonyodalmak nélkül',
    'index.partners.card2.text' => 'Az intelligens linkek automatikusan felismerik a látogató országát, és a régió hivatalos Forever webáruházához irányítják.',
    'index.partners.card3.title' => 'Professzionális online és offline jelenlét',
    'index.partners.card3.text' => 'A személyes alkalmazással és az NFC-kártyával műszaki ismeretek nélkül is könnyen megoszthatsz információkat.',
    'index.partners.card4.title' => 'Egyértelmű növekedési struktúra',
    'index.partners.card4.text' => 'A strukturált, 120 napos terv és a lépésről lépésre felépülő oktatás segít a partnereknek stabil és bővíthető rendszert kialakítani.',
    'index.faq.header' => 'Válaszok a gyakori kérdésekre',
    'index.faq.one.question' => 'Hogyan szerezhetem be a Forever Card alkalmazást?',
    'index.faq.one.answer' => 'A Forever Card App akkor válik elérhetővé számodra, amikor regisztrált Forever üzleti partner leszel, és a szponzorod a csapatunk tagja. A hozzáférés megadása után egy egyszerű bevezető folyamaton haladsz végig, amely bemutatja, hogyan aktiváld és állítsd be a személyes alkalmazásodat. Az alkalmazás a digitális központod: kiválaszthatod, mely blokkok jelenjenek meg benne, például videók, termékek, AI-tanácsadó, kapcsolat vagy oktatás, és mindent beállíthatsz műszaki ismeretek nélkül. Ha személyesen is dolgozol, egy ingyenes NFC-kártyát is kapsz postán, amelyet gyorsan leolvasva megnyitható az alkalmazásod.',
    'index.faq.two.question' => 'Hogyan működik a regisztráció nélküli rendelés és az ajánlás?',
    'index.faq.two.answer' => 'A Forever Card Club globális megosztásra tervezett, intelligens ajánlói hivatkozásokat használ. Amikor egy látogató rákattint a hivatkozásodra, vagy az alkalmazásodban kiválaszt egy terméket, majd a „megrendelés” lehetőséget választja, a rendszer automatikusan felismerheti az országát, és összekapcsolhatja az ottani hivatalos Forever webáruházzal. Az ajánlásod be van építve a hivatkozásba, így a vásárlás a hivatalos rendszer szabályainak megfelelően hozzád, mint ajánló partnerhez rendelhető. Fontos: a Forever Card Club nem értékesít termékeket. Minden vásárlás a vásárló országában működő hivatalos webáruházon keresztül történik.',
    'index.faq.three.question' => 'Mit kapok csapattagként?',
    'index.faq.three.answer' => 'Csapattagként egy teljes rendszert kapsz ahhoz, hogy online építsd a Forever üzletedet. Ennek része a személyes Forever Card App, ahol minden eszközöd és tartalmad egy helyen van, a hivatalos webáruházba irányító, globálisan működő intelligens ajánlói linkek, az alkalmazáson belüli MI-tanácsadó a termékekkel kapcsolatos útmutatáshoz és információkhoz, a lépésről lépésre felépített képzés a rendszer használatáról és az online üzletépítésről, a szokásaidhoz és céljaidhoz igazított, személyre szabott 120 napos terv, az elemzések arról, hogy mire kattintanak az emberek, honnan érkeznek, és mi működik a legjobban, valamint egy ingyenes NFC-kártya, amelyet offline kapcsolatteremtéshez a címedre küldünk. Közösségi támogatást is kapsz, például WhatsApp-csoportok és egyértelmű útmutatók formájában, hogy segítsenek kitartani és hosszú távú eredményeket elérni.',
    'index.faq.four.question' => 'Hogyan működik a 120 napos terv?',
    'index.faq.four.answer' => 'A 120 napos terv egy strukturált program, amely a kezdeti beállításoktól a szokások kialakításán át a következetes online kommunikáció, ajánlások, valamint a csapat és az ügyfélkör bővítésének rutinjáig vezeti a partnereket. Nem egy általános PDF. Úgy tervezték, hogy alkalmazkodjon az adott személyhez, a rendelkezésére álló időhöz, a kommunikációs stílusához, tapasztalati szintjéhez és céljaihoz. A terv egyértelmű lépéseket ad ahhoz, hogy mit állíts be az alkalmazásodban, hogyan használd az okos hivatkozásokat, hogyan mutasd be az információkat online, és hogyan építs olyan megismételhető rendszert, amelyet a későbbiekben a csapatod tagjai is átvehetnek.',
    'index.faq.five.question' => 'Mit csinál az AI-tanácsadó az alkalmazáson belül?',
    'index.faq.five.answer' => 'Az AI-tanácsadó segít a látogatóknak könnyebben eligazodni az információk között. A kérdéseik alapján releváns információkat és termékeket javasolhat, majd a következő lépéshez irányíthatja őket, például további tájékozódáshoz, kapcsolatfelvételhez vagy rendeléshez. Ha a látogató rendelni szeretne, az AI-tanácsadó intelligens hivatkozásokkal a hivatalos webáruházba irányíthatja, a partner ajánlói kapcsolatán keresztül. A partnereknek így kevesebbszer kell megismételniük az alapvető információkat, és a kommunikáció is világos és következetes maradhat.',
    'index.faq.contact_note' => 'Ha hozzáférésre van szükséged, vagy kérdésed van, vedd fel velünk a kapcsolatot a %s címen.',
    'index.faq.contact_link' => 'Kapcsolat oldal',
