    'qr_codes.title' => 'QR-kódok',
    'qr_codes.menu' => 'QR-kódok',
    'qr_codes.breadcrumb' => 'QR-kódok',
    'qr_codes.header' => 'QR-kódok',
    'qr_codes.subheader' => 'Készíts egyszerűen személyre szabható QR-kódokat, és mentsd el őket későbbi használatra.',
    'qr_codes.page_intro' => 'Hozz létre önálló QR-kódokat nyomtatáshoz, offline megosztáshoz, rendezvényekhez, termékekhez, WiFi-hez, kapcsolatok átadásához és sok más célra. Minden Forever Card App saját közvetlen QR-kódot is létrehozhat, ez a szekció pedig külön QR-munkaterületet biztosít, ahol egy helyen készítheted el és szerkesztheted őket.',
    'qr_codes.guide_title' => 'Külön QR-munkaterület nyomtatáshoz, offline megosztáshoz és szabályozott felhasználási esetekhez',
    'qr_codes.guide_text' => 'Ez a QR-kódok szekció olyan önálló QR-eszközök kezelésére szolgál, amelyeket egy adott alkalmazásképernyőn kívül szeretnél használni. Akkor használd, ha nyomtatható QR-kódokra, újra felhasználható kampánykódokra, eseményekhez vagy termékekhez vezető hozzáférési pontokra van szükséged, vagy olyan QR-kódot szeretnél, amelynek saját megjelenése és exportálási folyamata van.',
    'qr_codes.guide_card_1_title' => 'Az alkalmazás QR-kódjától külön',
    'qr_codes.guide_card_1_text' => 'Minden Forever Card App létrehozhat saját, közvetlen QR-kódot, de itt teljesen különálló QR-kódokat is készíthetsz más céloldalakhoz, hivatkozásokhoz, anyagokhoz és kampányokhoz.',
    'qr_codes.guide_card_2_title' => 'Nyomtatásra és offline használatra készült',
    'qr_codes.guide_card_2_text' => 'Ezek a QR-kódok ideálisak szórólapokra, névjegykártyákra, plakátokra, termékismertetőkre, rendezvényasztalokra és csomagolásra, valamint személyes megosztásra, amikor az emberek inkább beolvassák a kódot, mintsem begépelnék a címet.',
    'qr_codes.guide_card_3_title' => 'Megfelelő testreszabás és exportálás',
    'qr_codes.guide_card_3_text' => 'Állítsd be a QR-kód típusát, stílusát, színeit, kereteit, logóját, arculati elemeit és fájlformátumát, hogy a végleges kód illeszkedjen a felhasználási környezethez.',
    'qr_codes.guide_card_4_title' => 'Szerkeszd, és használd fel újra később',
    'qr_codes.guide_card_4_text' => 'A létrehozás után minden QR-kód továbbra is elérhető marad letöltésre, nyomtatásra, másolásra és későbbi finomításra, így nem kell az egészet elölről kezdened.',
    'qr_codes.empty_title' => 'Hozd létre az első QR-kódodat',
    'qr_codes.empty_text' => 'Kezdj egy önálló QR-kóddal, amely egy linkre, alkalmazásra, névjegyre, eseményre vagy nyomtatott anyagra mutat. A létrehozása után visszatérhetsz, hogy szerkeszd a stílust, a keretet, a márkajelzést és az exportálási formátumot.',
    'qr_codes.tour.create_title' => 'Önálló QR-kód létrehozása',
    'qr_codes.tour.create_text' => 'Akkor használd ezt a gombot, ha olyan QR-kódot szeretnél, amely nem csak egyetlen Forever Card App-oldalon érhető el. Ideális kampányokhoz, nyomtatott anyagokhoz, eseményekhez és ismételten megosztható offline tartalmakhoz.',
    'qr_codes.tour.guide_title' => 'Értsd meg, mikor érdemes ezt a részt választanod',
    'qr_codes.tour.guide_text' => 'Ez az útmutató elmagyarázza a különbséget az alkalmazáshoz tartozó QR-kódok és az önálló QR-kódanyagok között. Segít a felhasználóknak kiválasztani a megfelelő folyamatot, mielőtt létrehoznának vagy szerkesztenének valamit.',
    'qr_codes.tour.list_title' => 'Itt rendezetten tarthatod a QR-kódjaid gyűjteményét',
    'qr_codes.tour.list_text' => 'Ez a lista minden önálló QR-kód vezérlőközpontja lesz. Egy helyen találod majd az előnézetet, a nevet, a típust, a projekthez való kapcsolódást, az exportálási lehetőségeket és a szerkesztési hozzáférést.',
    'qr_codes.tour.row_title' => 'Minden sor egy újra felhasználható QR-eszköz',
    'qr_codes.tour.row_text' => 'Az itt található QR-kód egy URL-t, alkalmazáshivatkozást, eseményt, WiFi-kapcsolódást, vCardot, fizetési kérelmet vagy számos más beolvasási lehetőséget képviselhet. Idővel továbbfejlesztheted ugyanazt az eszközt.',
    'qr_codes.tour.actions_title' => 'Letöltés, nyomtatás, szerkesztés, másolat készítése',
    'qr_codes.tour.actions_text' => 'A jobb oldali műveletekkel különböző formátumokba exportálhatsz, megnyithatod a szerkesztést, lemásolhatsz egy bevált QR-kódot egy új kampányhoz, vagy törölheted a már nem szükséges régi elemeket.',
