    'qr_code_update.title' => 'QR-kód szerkesztése',
    'qr_code_update.header' => 'QR-kód szerkesztése',
    'qr_codes.editor.hero_title' => 'Alakíts egy egyszerű QR-kódot újra és újra használható, offline és digitális felületeket összekötő hozzáférési ponttá',
    'qr_codes.editor.hero_text' => 'Ebben a szerkesztőben a QR-kód gyakorlati, márkádhoz illő és valódi használatra kész eszközzé válik. Minden Forever Card App képes saját QR-kódot létrehozni, itt azonban külön is létrehozhatsz és finomíthatsz QR-kódokat nyomtatáshoz, kampányokhoz, eseményekhez, termékutakhoz, kapcsolatok megosztásához és sok más beolvasási helyzethez.',
    'qr_codes.editor.hero_card_1_title' => 'Válaszd ki a beolvasás eredményét',
    'qr_codes.editor.hero_card_1_text' => 'Döntsd el, hogy a QR-kód URL-t, névjegykártyát, fizetési folyamatot, WiFi-kapcsolatot, üzenetvázlatot, eseményt, helyszínt vagy más támogatott műveletet nyisson-e meg.',
    'qr_codes.editor.hero_card_2_title' => 'Igazítsd a környezethez',
    'qr_codes.editor.hero_card_2_text' => 'Módosítsd a stílust, a színeket, a keretet, a márkajelzést és az opcionális logót, hogy a QR-kód illeszkedjen a szórólaphoz, névjegykártyához, termékismertetőhöz, prezentációhoz vagy rendezvényanyaghoz.',
    'qr_codes.editor.hero_card_3_title' => 'Nyomtatás előtti előnézet',
    'qr_codes.editor.hero_card_3_text' => 'A QR-kód kinyomtatása vagy nyilvános terjesztése előtt teszteld az élő előnézetet, az olvashatóság-ellenőrzést és a letöltési lehetőségeket.',
    'qr_codes.editor.hero_card_4_title' => 'Használd újra ahelyett, hogy mindent újraalkotnál',
    'qr_codes.editor.hero_card_4_text' => 'Ha egy QR-kód jól működik, új kampányokhoz inkább szerkeszd, másold le vagy exportáld, ahelyett hogy minden alkalommal újat készítenél.',
    'qr_codes.editor.tour.intro_title' => 'QR-szerkesztő áttekintése',
    'qr_codes.editor.tour.intro_text' => 'Ezen az oldalon önálló QR-kódot hozhatsz létre vagy alakíthatsz át úgy, hogy kinyomtathasd, megoszthasd, exportálhasd, és sokféle helyzetben újra felhasználhasd.',
    'qr_codes.editor.tour.type_title' => 'Válaszd ki, mit tegyen a vizsgálat',
    'qr_codes.editor.tour.type_text' => 'A QR-kód típusa határozza meg, mi történik beolvasáskor: megnyílik egy link, elmenthetők az elérhetőségek, elindítható egy üzenet, csatlakozhatsz a WiFi-hálózathoz, megjeleníthető egy fizetési kérelem és még sok más.',
    'qr_codes.editor.tour.basics_title' => 'Kezdd a névvel és az alapadatokkal',
    'qr_codes.editor.tour.basics_text' => 'Adj egyértelmű belső nevet a QR-kódnak, és töltsd ki a kötelező tartalmi mezőket. Ez az alapvető adatkészlet kerül a kódba.',
    'qr_codes.editor.tour.style_title' => 'Formázd magát a QR-mintát',
    'qr_codes.editor.tour.style_text' => 'A stílus a QR-kód moduljainak és szemeinek alakját szabályozza. Ez akkor hasznos, ha azt szeretnéd, hogy a QR-kód vizuálisan illeszkedjen egy márkához, kampányhoz vagy nyomtatott anyaghoz.',
    'qr_codes.editor.tour.colors_title' => 'A kontraszt és az áttekinthetőség szabályozása',
    'qr_codes.editor.tour.colors_text' => 'A színek nem csupán esztétikai szempontból fontosak. A jó kontraszt elengedhetetlen ahhoz, hogy a kód megbízhatóan beolvasható legyen, különösen, ha a QR-kódot kinyomtatják vagy nem ideális fényviszonyok között nézik.',
    'qr_codes.editor.tour.frame_title' => 'Adj kiegészítő információt a QR-kódhoz',
    'qr_codes.editor.tour.frame_text' => 'A keretek tudatosabb megjelenést adnak a QR-kódnak, és cselekvésre ösztönző felhívást vagy címkét is hozzáadhatsz, hogy az emberek azonnal megértsék, miért érdemes beolvasniuk.',
    'qr_codes.editor.tour.branding_title' => 'Gondosan helyezd el a logót és a márkázott rétegeket',
    'qr_codes.editor.tour.branding_text' => 'A márkajelzési beállítások lehetővé teszik logók és képek elhelyezését a QR-kód kompozíciójában, de ezeket alaposan tesztelni kell, hogy a kód jól olvasható maradjon.',
    'qr_codes.editor.tour.options_title' => 'Technikai beállítások befejezése',
    'qr_codes.editor.tour.options_text' => 'A méret, a margó, a kódolás, a hibajavítás és a projekt rendszerezése segíti a QR-kód megfelelő működését exportáláskor és éles használatban.',
    'qr_codes.editor.tour.preview_title' => 'Nézd meg élőben a végleges QR-kódot',
    'qr_codes.editor.tour.preview_text' => 'Az előnézetben ellenőrizheted, hogy a QR-kód továbbra is tisztán látható és beolvasható-e, mielőtt letöltöd, kinyomtatod vagy megosztod.',
    'qr_codes.editor.tour.download_title' => 'Kimenet előkészítése nyomtatáshoz vagy kézbesítéshez',
    'qr_codes.editor.tour.download_text' => 'Exportálj SVG-, PNG-, JPG- vagy WEBP-fájlt attól függően, hogy nyomtatási minőségre, átlátszóságra, prezentációhoz használható formátumra vagy gyors terjesztésre van szükséged.',
    'qr_codes.editor.tour.save_title' => 'Mentsd, teszteld, majd élesítsd',
    'qr_codes.editor.tour.save_text' => 'Mentés után legalább egy telefonon olvasd be a QR-kódot, mielőtt nyilvánosan használni kezdenéd. Ez különösen fontos keretek, színátmenetek, logók vagy nyomtatott anyagok esetén.',
    'biolink_block_delete.header' => 'Blokk törlése',
    'biolink_block_delete.subheader' => 'Az FCC-blokkal kapcsolatos összes adat véglegesen törlődik. Ez a művelet nem vonható vissza.',
    'biolink_block_delete.success_message' => 'Az FCC-blokk törlése sikeresen megtörtént.',
    'biolink_block.title' => 'FCC-blokk',
    'links_statistics.title' => 'Linkstatisztikák',
    'links_statistics.menu' => 'Linkstatisztikák',
    'links_statistics.breadcrumb' => 'Linkstatisztikák',
    'links_statistics.header' => 'Linkstatisztikák',
    'link.header.subheader' => 'Forever Card App: %s',
    'link.header.short_link_subheader' => 'Rövid link beállításai: %s',
    'link.short_editor.hero_title' => 'Alakítsd az egyszerű, rövid URL-t szabályozott átirányítási folyamattá.',
    'link.short_editor.hero_text' => 'Ebben a szerkesztőben válik egy rövid link stratégiai eszközzé. Az álnév és a céloldal mellett időzítést, UTM-követést, jelszavas védelmet, alkalmazáslinkelést, álcázást, eszköz vagy hely szerinti célzást, HTTP-viselkedést és egyéb speciális beállításokat is hozzáadhatsz.',
    'link.short_editor.hero_card_1_title' => 'Kezdd az alapokkal',
    'link.short_editor.hero_card_1_text' => 'Add meg a cél-URL-t, válassz egy rövid aliast, és döntsd el, melyik domaint használja a rövid link.',
    'link.short_editor.hero_card_2_title' => 'Döntsd el, hogyan működjön',
    'link.short_editor.hero_card_2_text' => 'Szabályozd, mikor működjön a link, hová irányítson át, mi történjen a lejárata után, és továbbítsa-e a lekérdezési paramétereket.',
    'link.short_editor.hero_card_3_title' => 'Kövesd nyomon és szabd személyre',
    'link.short_editor.hero_card_3_text' => 'Adj hozzá UTM-címkéket, pixeleket, cloaking-metaadatokat és alkalmazáslinkeket, hogy minden kattintás magában hordozza a szükséges kontextust.',
    'link.short_editor.hero_card_4_title' => 'Védd és optimalizáld',
    'link.short_editor.hero_card_4_text' => 'Használj jelszavakat, érzékeny tartalomra vonatkozó figyelmeztetéseket, célközönség-beállításokat és átirányítási kódokat az egyes kampányokhoz és célközönségekhez igazítva.',
    'link.short_editor.form_title' => 'Mit állíthatsz be egy rövid linken',
    'link.short_editor.form_text' => 'Csak a szükséges részeket nyisd meg, vagy haladj végig az oktatóanyagon lépésről lépésre. Az alábbi csoportok mindegyike a rövid linkek használatának egy-egy rétegét szabályozza, az egyszerű átirányítástól a fejlett kampánylogikáig.',
    'link.short_editor.card_1_title' => 'Tiszta indulásokhoz',
    'link.short_editor.card_1_text' => 'Állítsd be a célcímet, az aliast, a domaint és az átirányítási kódot, hogy a hivatkozás már az első megosztástól kezdve pontosan úgy működjön, ahogyan szeretnéd.',
    'link.short_editor.card_2_title' => 'Kampányokhoz és jelentésekhez',
    'link.short_editor.card_2_text' => 'Adj hozzá UTM-értékeket, pixeleket, jelentéseket és projekteket, hogy a forgalmat megfelelően mérhesd és csoportosíthasd.',
    'link.short_editor.card_3_title' => 'Speciális működéshez',
    'link.short_editor.card_3_text' => 'Állítsd be az elérhetőség ütemezését, a lejárati szabályokat és a hozzáférés védelmét, célozz meg közönségeket, vagy szükség esetén rejtsd el a céloldalt.',
    'link.short_editor.tour.intro_title' => 'A rövidlink-szerkesztő áttekintése',
    'link.short_editor.tour.intro_text' => 'Ezen az oldalon egy rövid hivatkozás összes speciális beállítását megtalálod. A cél egyszerű: segítsünk megérteni, hogy az egyes beállítások mit módosítanak, mielőtt elmented őket.',
    'link.short_editor.tour.basics_title' => 'Először az alapok',
    'link.short_editor.tour.basics_text' => 'Itt adhatod meg, hová mutasson a rövid link, milyen aliast használjon, és melyik domainen jelenjen meg. Ezek az átirányítás alapvető beállításai.',
    'link.short_editor.tour.app_linking_title' => 'Mobilalkalmazások közvetlen megnyitása',
    'link.short_editor.tour.app_linking_text' => 'Az alkalmazáslinkelés lehetővé teszi, hogy a támogatott mobilos hivatkozások a böngésző helyett a natív alkalmazásban nyíljanak meg, ami javíthatja a telefonhasználók élményét.',
    'link.short_editor.tour.temporary_title' => 'Időzítési és lejárati szabályok beállítása',
    'link.short_editor.tour.temporary_text' => 'Ebben a részben beállíthatod az elérhetőségi időszakot, korlátozhatod a kattintásokat, vagy megadhatod, hová kerüljenek az emberek a link lejárta után. Kiválóan alkalmas akciókhoz, termékbevezetésekhez és időkorlátos kampányokhoz.',
    'link.short_editor.tour.utm_title' => 'Analitikai kontextus hozzáadása',
    'link.short_editor.tour.utm_text' => 'Az UTM-paraméterek segítenek az analitikai eszközöknek megérteni a forgalom forrását, médiumát és kampányát. Ez az egyik leghasznosabb lehetőség a kampányelnevezések egységesítésére.',
    'link.short_editor.tour.protection_title' => 'Szükség esetén védd a hozzáférést',
    'link.short_editor.tour.protection_text' => 'A jelszavak és az érzékeny tartalomra figyelmeztető üzenetek hasznosak, ha nem szeretnéd teljesen nyilvánossá tenni a hivatkozást, vagy ha a látogatóknak még a továbblépés előtt több információra van szükségük.',
    'link.short_editor.tour.targeting_title' => 'Irányíts különböző közönségeket különböző céloldalakra',
    'link.short_editor.tour.targeting_text' => 'A célzásnak köszönhetően egyetlen rövid hivatkozás az ország, város, eszköz, operációs rendszer, böngésző nyelve vagy rotációs szabályok alapján változhat. Ez hatékony eszköz szegmentált kampányokhoz.',
    'link.short_editor.tour.cloaking_title' => 'Szabályozd, milyen előnézetet látnak az emberek',
    'link.short_editor.tour.cloaking_text' => 'Az álcázás átirányítás előtt módosítja a megjelenített címet, leírást, képet és más metaadatokat. Akkor hasznos, ha azt szeretnéd, hogy a megosztott előnézet illeszkedjen a kampány üzenetéhez.',
    'link.short_editor.tour.http_title' => 'Válaszd ki az átirányítás típusát',
    'link.short_editor.tour.http_text' => 'A 301, 302, 307 és 308 nem azonos. Ez a szakasz határozza meg, hogy az átirányítás véglegesnek vagy ideiglenesnek minősül-e, és hogyan kezeljék azt a böngészők.',
    'link.short_editor.tour.advanced_title' => 'Végezd el a speciális beállításokkal',
    'link.short_editor.tour.advanced_text' => 'A projektek, az üdvözlőoldalak, az értesítések, a lekérdezések továbbítása és a kapcsolódó lehetőségek itt találhatók, így a rövid linket egy tágabb munkafolyamatba illesztheted.',
    'link.short_editor.tour.save_title' => 'Mentés és tesztelés',
    'link.short_editor.tour.save_text' => 'Mentés után teszteld a rövid hivatkozást asztali gépen és mobilon, majd ellenőrizd a statisztikákat, hogy az átirányítások, a forrásmegjelölés és a célzás a várakozásaid szerint működik-e.',
    'link.settings.background_brightness' => 'Háttér fényereje',
