    'fcc.page.contact_business_text' => 'Ha a Forever Living Products üzleti partnerévé szeretnél válni, megrendeled az induló csomagot, és hozzáférnél a Forever Card Club összes előnyéhez, itt kezdheted el.',
    'fcc.page.contact_app_title' => 'Alkalmazás megnyitása',
