    'fcc.page.open' => 'Megnyitás',
    'fcc.page.semantics_heading' => 'Mi az a Forever Card Club (FCC)?',
    'fcc.page.semantics_summary' => 'A Forever Card Club (FCC) egy mindent egyben kínáló digitális üzleti rendszer a Forever Living Products partnerei számára. Az FCC egyetlen üzleti folyamatban egyesíti a személyes alkalmazást, az intelligens ajánlói linkeket, az AI-termékasszisztenseket, az érdeklődőket kezelő tölcsérlogikát, az oktatást, az elemzéseket és a fizikai NFC-kártyát.',
    'fcc.page.semantics_fact_1' => 'A Forever Card Club nem a Forever Living Products hivatalos weboldala vagy áruháza, hanem partnerek számára létrehozott független rendszer.',
    'fcc.page.semantics_fact_2' => 'A Forever Card App az a személyes alkalmazás, amelyet minden tag megkap, az FCC pedig a tágabb rendszert jelenti.',
    'fcc.page.semantics_fact_3' => 'A termékvásárlások az ügyfél országában működő hivatalos Forever webáruházban történnek.',
    'fcc.page.semantics_fact_4' => 'A rendszert online megosztásra, ajánlások továbbítására, érdeklődők gyűjtésére, AI-útmutatásra és a Forever üzlet fejlesztésére tervezték.',
    'fcc.page.semantics_solves_heading' => 'Miben segít az FCC?',
    'fcc.page.semantics_solve_1' => 'Egy központi hely a partneralkalmazás, a tartalmak, a termékek és a kapcsolatfelvételi lehetőségek számára.',
    'fcc.page.semantics_solve_2' => 'Intelligensebb átirányítás a látogató országának hivatalos Forever webáruházába.',
    'fcc.page.semantics_solve_3' => 'Érdeklődők gyűjtése és gyorsabb utánkövetés az érdeklődés vagy ajánlás után.',
    'fcc.page.semantics_solve_4' => 'Mesterséges intelligencia által támogatott termékfelfedezés és útmutatás a következő lépéshez a rendszeren belül.',
    'fcc.page.semantics_solve_5' => 'Átlátható átjárás az offline kapcsolattartástól az NFC-n vagy QR-kódon keresztül az online munkafolyamatig.',
    'fcc.page.term_description' => 'A Forever Card Club (FCC) egy minden az egyben digitális üzleti rendszer a Forever Living Products partnereinek. Személyes alkalmazást, intelligens ajánlói linkeket, AI-terméktanácsadókat, érdeklődőszerző tölcsérlogikát, oktatást, analitikát és a partner tartalmaihoz és ajánlásaihoz kapcsolódó fizikai NFC-kártyát kínál.',
    'fcc.page.workflow_heading' => 'Hogyan működik az FCC a gyakorlatban?',
    'fcc.page.workflow_intro' => 'Az első érdeklődéstől a kapcsolatfelvételig vagy a vásárlásig az FCC egyetlen üzleti folyamatba kapcsolja össze a legfontosabb lépéseket.',
    'fcc.page.workflow_step_1_title' => 'Belépés',
