    'fcc_ai.platform.title' => 'A platform áttekintése',
    'fcc_ai.platform.note_admin' => 'A technikai részletek az alul található, lenyitható részekben továbbra is elérhetők, így a főképernyő letisztult marad.',
    'fcc_ai.platform.note_user' => 'Egy helyen láthatod, hogyan kapcsolható be az AI az alkalmazásban, hogyan működik a Coach, és hol követheted a beszélgetéseket és az érdeklődőket.',
    'fcc_ai.platform.list.app_blocks_title' => 'AI-blokkok az alkalmazásban',
    'fcc_ai.platform.list.app_blocks_text' => 'A nyilvános AI úgy kapcsolható be, hogy hozzáadsz egy AI-blokkot az FCC alkalmazás beállításai között. Ezután az AI megjelenik az alkalmazásban.',
    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'A Coach mindig elérhető az FCC-ben, kapcsolódik a fejlődési tervedhez, és a platform, a közösségi média, a kommunikáció és az üzletfejlesztés terén nyújt segítséget.',
    'fcc_ai.platform.list.single_ai_title' => 'Alkalmazásonként egy AI',
    'fcc_ai.platform.list.single_ai_text' => 'Egy FCC Appban egyszerre csak egy AI-tanácsadó lehet aktív. Ha már hozzáadtál egy AI-blokkot, egy újabb hozzáadásakor figyelmeztetés jelenik meg.',
    'fcc_ai.platform.list.leads_title' => 'AI érdeklődők',
    'fcc_ai.platform.list.leads_text' => 'Az AI-érdeklődők a meglévő /data beérkező levelek mappába kerülnek, és a kapcsolódó beszélgetéshez lesznek kapcsolva.',
    'fcc_ai.guide.title' => 'Az FCC AI használata',
    'fcc_ai.guide.subtitle' => 'Ezek a rövid útmutatók bemutatják, mire képes az egyes AI-eszköz, és hogyan használhatod ki őket a mindennapi munkában.',
    'fcc_ai.guide.coach.title' => 'AI Coach',
    'fcc_ai.guide.coach.summary' => 'Támogatás az FCC-vel kapcsolatos munkához, a fejlődési tervedhez és a következő gyakorlati lépésekhez.',
    'fcc_ai.guide.coach.intro' => 'Az FCC Coach a platformon belüli személyes asszisztensed. Kapcsolódik a fejlődési tervedhez, és segít tisztán látni, mi a leghasznosabb következő lépés.',
    'fcc_ai.guide.coach.point_1' => 'Segíthet a tervezésben, a prioritások meghatározásában, a fókuszálásban és a következő lépés kiválasztásában, amikor elakadsz vagy nem tudod, mit tegyél.',
    'fcc_ai.guide.coach.point_2' => 'Ötleteket ad a tartalomhoz, a kommunikációhoz, a közösségi médiához és a mindennapi teendőkhöz, amelyek támogatják a vállalkozás növekedését.',
    'fcc_ai.guide.coach.point_3' => 'Végigvezet a növekedési terveden, és az aktuális igényeidhez kapcsolódó tanácsokat ad.',
    'fcc_ai.guide.coach.tip' => 'Akkor hozhatod ki belőle a legtöbbet, ha világosan leírod, hol tartasz, mit szeretnél elérni, és most milyen segítségre van szükséged.',
    'fcc_ai.guide.sales.title' => 'AI az értékesítéshez, ajánlásokhoz és üzleti együttműködéshez',
    'fcc_ai.guide.sales.summary' => 'Nyilvános AI, amely termékeket ajánl, felhasználja a blog tartalmát, és felismeri az együttműködés iránti érdeklődést.',
    'fcc_ai.guide.sales.intro' => 'Ez az AI az FCC-alkalmazásod látogatóival beszélget, segít nekik embereknek vagy háziállatoknak szánt termékeket találni, és a következő lépés, a vásárlás vagy az üzleti együttműködés felé tereli őket.',
    'fcc_ai.guide.sales.point_1' => 'Válaszol a kérdésekre, termékeket ajánl, és a látogatót a részletesebb magyarázatot adó megfelelő FCC-blogcikkhez irányíthatja.',
    'fcc_ai.guide.sales.point_2' => 'Végigkíséri a látogatót a teljes folyamaton, az első kérdéstől a blogon folytatott beszélgetésig vagy a kapcsolatfelvételig.',
    'fcc_ai.guide.sales.point_3' => 'Az érdeklődő látogatóktól adatokat gyűjthet, és elmentheti az érdeklődőt, hogy a partner később felvehesse vele a kapcsolatot.',
    'fcc_ai.guide.sales.point_4' => 'Felismerheti az üzleti érdeklődést, és támogathatja a szponzorálást azzal, hogy a látogatót a következő érdemi lépés felé irányítja.',
    'fcc_ai.guide.sales.tip' => 'Akkor működik a legjobban, ha a hangnem világos, a szabályok következetesek, az ajánlási logika pedig jól elmagyarázott.',
    'fcc_ai.guide.settings.title' => 'Tanácsadói beállítások',
    'fcc_ai.guide.settings.summary' => 'Itt alakíthatod ki, hogyan szólaljon meg a nyilvános AI, hogyan válaszoljon, és mit emeljen ki.',
    'fcc_ai.guide.settings.intro' => 'A nyilvános AI-tanácsadó beállításainál úgy módosíthatod a kommunikációt, hogy az illeszkedjen a stílusodhoz, a közönségedhez és az alkalmazás céljához.',
    'fcc_ai.guide.settings.point_1' => 'Az asszisztens neve és nyelve határozza meg, hogyan mutatkozik be az AI, és milyen nyelven kommunikál természetesen.',
    'fcc_ai.guide.settings.point_2' => 'A hangnem segít abban, hogy az AI tanácsadó, támogató, barátságos vagy közvetlenebb legyen, attól függően, mit szeretnél.',
    'fcc_ai.guide.settings.point_3' => 'A személyiségre vonatkozó utasításokban írd le, milyen stílust szeretnél: melegebb hangnemet, rövidebb válaszokat, több kérdést, nagyobb hangsúlyt a termékekre vagy inkább az üzletre.',
    'fcc_ai.guide.settings.point_4' => 'A szabályok és korlátozások között határozd meg, mit említsen meg mindig az AI, mit kerüljön el, és hogyan fogalmazza meg az ajánlásokat.',
    'fcc_ai.guide.settings.tip' => 'A rövid, konkrét útmutatások általában működnek a legjobban. Úgy fogalmazz, mintha azt magyaráznád el, hogyan beszéljen egy jó tanácsadó a látogatóval.',
    'fcc_ai.guide.inbox.title' => 'AI-bejövő üzenetek az elmúlt 30 napban',
    'fcc_ai.guide.inbox.summary' => 'Itt követheted a beszélgetéseket és a leadeket, valamint finomíthatod az AI-csevegések kommunikációját.',
    'fcc_ai.guide.inbox.intro' => 'Az AI beérkező üzenetei között láthatod, hogyan beszélgetett az asszisztens valódi felhasználókkal. Ez a legjobb hely a minőség ellenőrzésére és az asszisztens folyamatos fejlesztésére.',
    'fcc_ai.guide.inbox.point_1' => 'Nyisd meg a beszélgetéseket, és nézd át, hol válaszolt jól az AI, és hol lehetne a válasza egyértelműbb vagy hasznosabb.',
    'fcc_ai.guide.inbox.point_2' => 'Figyeld, mely kérdések ismétlődnek gyakran, hogy javíthasd a hangnemet, a személyiségre vonatkozó utasításokat és a szabályokat.',
    'fcc_ai.guide.inbox.point_3' => 'Ha a felhasználók továbbra is több magyarázatot kérnek, rövidítsd le a válaszokat, adj egyértelműbb lépéseket, vagy irányítsd őket hatékonyabban a bloghoz vagy a kapcsolatfelvételhez.',
    'fcc_ai.guide.inbox.point_4' => 'Kövesd nyomon az AI által szerzett érdeklődőket, és használd ezt annak megértésére, hogy a csevegés hol segít leginkább az értékesítésben és a szponzorálásban.',
    'fcc_ai.guide.inbox.tip' => 'Ha többször is ugyanazzal a problémával találkozol, azonnal módosítsd a tanácsadó beállításait. A hangnem és a szabályok apró változtatásai gyakran nagy javulást hoznak.',
